class ReportRenderer {
  render(data: any, format: string) {
    if (format === 'pdf') return this.renderPdf(data);
    else if (format === 'html') return this.renderHtml(data);
    else return this.renderText(data);
  }
}

class PaymentService {
  process(amount: number) {
    if (config.gateway === 'stripe') {
      StripeSDK.charge(amount);
    } else if (config.gateway === 'paypal') {
      PayPalSDK.pay(amount);
    } else {
      throw new Error('Unknown gateway');
    }
  }
}

