class ReportGenerator {
  generate(data: any, format: string) {
    if (format === 'json') return JSON.stringify(data);
    if (format === 'csv') return toCsv(data);
    if (format === 'html') return toHtml(data);
    throw new Error('Unsupported format');
  }
}

// Version B
interface Renderer { render(data:any): string }
class JsonRenderer implements Renderer { render(d:any){ return JSON.stringify(d); } }
class CsvRenderer implements Renderer { render(d:any){ return toCsv(d); } }
class ReportGeneratorV2 {
  constructor(private renderer: Renderer) {}
  generate(data:any) { return this.renderer.render(data); }
}
